insert into public.anti_bloat_rows (position, layer, retained, pruned, impact)
select position, layer, retained, pruned, impact from jsonb_populate_recordset(null::public.anti_bloat_rows, $j$[{"position":1,"layer":"L0 Foundation","retained":"parking_lot + rkyv 0.8","pruned":"std::sync::Mutex, bincode","impact":"Zero-copy lock ordering, -12 MB memory"},{"position":2,"layer":"L1 Database","retained":"SQLite WAL (authoritative_audit.db)","pruned":"Dual SQLite DBs, PostgreSQL","impact":"Enforces foreign keys, atomic WAL commits"},{"position":3,"layer":"L1 Sandbox","retained":"cgroup.kill / JobObjects / Seatbelt","pruned":"In-process timeouts, SIGKILL","impact":"Atomically reaps 100% of forked subtrees in <15ms"},{"position":4,"layer":"L2 VCS","retained":"Embedded jj-lib v0.46.0","pruned":"git CLI subprocesses, .git/index.lock","impact":"Zero lock contention across 20 concurrent agents"},{"position":5,"layer":"L2 AST Graph","retained":"Tree-sitter 0.27 + petgraph","pruned":"LSP indexing daemons, ctags","impact":"200k-file AST symbol maps in <45 MB RSS"},{"position":6,"layer":"L3 Protocols","retained":"rmcp v3.5.1 + 4-Meta-Tool Gateway","pruned":"Full 200-tool MCP prompt dumps","impact":"Drops tool overhead from 40k to 480 tokens"},{"position":7,"layer":"L3 UI Mods","retained":"wasmtime QuickJS-WASM (wasm32-wasip1)","pruned":"V8 Workers, Node vm2","impact":"<4 MB heap per mod, -600 MB RAM"}]$j$::jsonb);
